"""Runs the real prepare command on small generated datasets."""

import numpy as np
import pytest
import soundfile
import yaml
from PIL import Image

from ml.common import prepare
from ml.common.manifest import read_manifest, unseen_evaluation_frame


def registry(tmp_path, monkeypatch, name, modality, adapter, split):
    entry = {
        name: {
            "title": name, "modality": modality, "adapter": adapter, "role": "Testing",
            "licence": "None", "access": "manual", "homepage": "https://example.com",
            "instructions": "Generated by the test.", "split": split, "known_biases": ["Generated data."],
        }
    }
    path = tmp_path / "datasets.yaml"
    path.write_text(yaml.safe_dump(entry), encoding="utf-8")
    monkeypatch.setattr(prepare, "REGISTRY_PATH", path)


def tone(frequency: float) -> np.ndarray:
    times = np.arange(16000) / 16000
    return (0.5 * np.sin(2 * np.pi * frequency * times)).astype(np.float32)


def test_audio_dataset_end_to_end(tmp_path, monkeypatch):
    raw = tmp_path / "data" / "raw" / "wavefake"
    (raw / "LJSpeech-1.1" / "wavs").mkdir(parents=True)
    (raw / "generated_audio" / "ljspeech_melgan").mkdir(parents=True)
    for index in range(20):
        soundfile.write(raw / "LJSpeech-1.1" / "wavs" / f"LJ{index:03}.wav", tone(200 + index), 16000)
        soundfile.write(
            raw / "generated_audio" / "ljspeech_melgan" / f"LJ{index:03}_gen.wav", tone(500 + index), 16000
        )
    registry(tmp_path, monkeypatch, "wavefake", "audio", "ml.audio.datasets:wavefake_records", {"strategy": "grouped"})

    path = prepare.run("wavefake", tmp_path / "data", tmp_path / "cards", workers=1, limit=None)

    frame = read_manifest(path)
    assert len(frame) == 40
    assert set(frame["split"]) == {"train", "val", "test"}
    assert frame.groupby("group_id")["split"].nunique().max() == 1
    processed = tmp_path / "data" / "processed" / "wavefake"
    assert all((processed / item).exists() for item in frame["path"])
    assert "## Known biases" in (tmp_path / "cards" / "wavefake.md").read_text(encoding="utf-8")


def test_image_dataset_end_to_end_with_unseen_generator(tmp_path, monkeypatch):
    raw = tmp_path / "data" / "raw" / "genimage"
    rng = np.random.default_rng(0)
    for generator, folder, count in (("sd", "ai", 30), ("BigGAN", "ai", 10), ("sd", "nature", 30)):
        directory = raw / generator / "train" / folder
        directory.mkdir(parents=True)
        for index in range(count):
            pixels = rng.integers(0, 255, (64, 96, 3), dtype=np.uint8)
            Image.fromarray(pixels).save(directory / f"{generator}_{folder}_{index}.png")
    registry(
        tmp_path, monkeypatch, "genimage", "image", "ml.image.datasets:genimage_records",
        {"strategy": "grouped", "heldout_generators": ["biggan"]},
    )

    path = prepare.run("genimage", tmp_path / "data", tmp_path / "cards", workers=1, limit=None)

    frame = read_manifest(path)
    assert set(frame.loc[frame["generator_name"] == "biggan", "split"]) == {"unseen_test"}
    evaluation = unseen_evaluation_frame(frame)
    assert evaluation["label"].nunique() == 2
    sample = tmp_path / "data" / "processed" / "genimage" / frame["path"].iloc[0]
    with Image.open(sample) as image:
        assert image.size == (224, 224)


def test_manual_dataset_without_files_stops_with_instructions(tmp_path, monkeypatch):
    registry(tmp_path, monkeypatch, "genimage", "image", "ml.image.datasets:genimage_records", {"strategy": "grouped"})
    with pytest.raises(SystemExit, match="Generated by the test"):
        prepare.run("genimage", tmp_path / "data", tmp_path / "cards", workers=1, limit=None)


def test_unknown_dataset_lists_choices(tmp_path, monkeypatch):
    registry(tmp_path, monkeypatch, "genimage", "image", "ml.image.datasets:genimage_records", {"strategy": "grouped"})
    with pytest.raises(SystemExit, match="Choose from: genimage"):
        prepare.run("nope", tmp_path / "data", tmp_path / "cards", workers=1, limit=None)
